 public static final BlockPos P=new BlockPos(3040,205,8),M=P.above(2),CHEST=P.east(12);public static volatile boolean ready;static int stage,ticks;static long due;static ServerPlayer actor;static InfusionMatrix matrix;static boolean collapsing,seenReload;static FluxRiftEntity galleryRift;
