 static InfusionPedestal pedestal(ServerLevel l,BlockPos p,ItemStack stack){put(l,p,InfusionContent.ARCANE.get().defaultBlockState());var t=(InfusionPedestal)l.getBlockEntity(p);check(t.setItem(stack),"Pedestal refused item");return t;}
 static void basics(ServerLevel l){
  for(int wear=0;wear<8;wear++){var stack=PrimordialPearl.worn(wear);check(stack.getMaxStackSize()==1&&!stack.isDamageableItem()&&!stack.isEnchantable(),"Repairable/enchantable/stackable pearl");var input=CraftingInput.of(1,1,List.of(stack));check(l.recipeAccess().getRecipeFor(RecipeType.CRAFTING,input,l).isEmpty(),"Pearl split recipe recreated aspect-bearing motes");var remainder=CraftingRecipe.defaultCraftingReminder(input).getFirst();check(wear==7?remainder.isEmpty():PrimordialPearl.wear(remainder)==wear+1&&remainder.getCount()==1,"Native crafting remainder not exact");check(PrimordialPearl.wear(stack)==wear,"Remainder changed input in preview");check(l.recipeAccess().getRecipeFor(RecipeType.CRAFTING,CraftingInput.of(2,1,List.of(stack,stack.copy())),l).isEmpty(),"Pearl repair recipe accepted");}
  var conversion=l.recipeAccess().getRecipeFor(RecipeType.CRAFTING,CraftingInput.of(1,1,List.of(item("primordial_nugget"))),l).orElseThrow().value().assemble(CraftingInput.of(1,1,List.of(item("primordial_nugget"))));check(PrimordialPearl.wear(conversion)==7,"Legacy fragment regained uses");
  put(l,P.west(7),ArcaneContent.WORKBENCH.get().defaultBlockState());var work=(ArcaneWorkbenchEntity)l.getBlockEntity(P.west(7));actor.setPos(Vec3.atCenterOf(P.west(7)));ResearchService.grant(actor,"ESSENTIASMELTERVOID");work.inventory.setItem(1,item("metal_alchemical"));work.inventory.setItem(7,item("metal_alchemical"));work.inventory.setItem(3,item("plate_void"));work.inventory.setItem(5,item("plate_void"));work.inventory.setItem(4,PrimordialPearl.worn(4));work.inventory.setItem(9+ArcaneRecipe.PRIMALS.indexOf("terra"),CrystalContent.essence("terra",1));work.inventory.setItem(9+ArcaneRecipe.PRIMALS.indexOf("ignis"),CrystalContent.essence("ignis",1));AuraData.get(l).put(AuraCell.key(P.getX()>>4,P.getZ()>>4),new AuraCell(500,500,0));AuraData.get(l).put(AuraCell.key((P.getX()-7)>>4,P.getZ()>>4),new AuraCell(500,500,0));int vis=work.availableVis();check(work.craft(actor)&&work.inventory.getItem(15).is(SimpleContent.ITEMS.get("metal_alchemical_advanced").get())&&PrimordialPearl.wear(work.inventory.getItem(4))==5&&work.availableVis()==vis-200,"Paid arcane recipe lost remainder/cost");
  Thaumcraft.LOGGER.info("PRIMORDIAL_CRAFT_OK: all eight native crafting remainders, nonmutating previews, repair rejection, conserving legacy exchange and paid advanced arcane recipe");
 }
 static void altar(ServerLevel l){
  put(l,M,InfusionContent.MATRIX.get().defaultBlockState());pedestal(l,M.below(2),item("focus_2"));pedestal(l,M.offset(-3,-2,0),item("quicksilver"));pedestal(l,M.offset(0,-2,3),PrimordialPearl.worn(5));pedestal(l,M.offset(3,-2,0),item("quicksilver"));pedestal(l,M.offset(0,-2,-3),new ItemStack(Items.NETHER_STAR));
  for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})for(int y:new int[]{-2,-1})put(l,M.offset(x,y,z),SimpleContent.BLOCKS.get("stone_arcane").get().defaultBlockState());
  for(var entry:Map.of("praecantatio",25,"ordo",50,"vacuos",100).entrySet()){var pos=M.offset(entry.getKey().equals("ordo")?4:-4,-2,entry.getKey().equals("vacuos")?4:0);put(l,pos,AlchemyContent.JAR.get().defaultBlockState());check(((AlchemyMachine)l.getBlockEntity(pos)).insertEssence(entry.getKey(),entry.getValue(),false),"Jar payment setup");}
  for(int x:new int[]{-5,5})for(int z:new int[]{-5,-3,3,5})put(l,M.offset(x,-2,z),InfusionContent.STABILIZER.get().defaultBlockState());
  matrix=(InfusionMatrix)l.getBlockEntity(M);actor.setPos(Vec3.atCenterOf(M));ResearchService.grant(actor,"INFUSION");ResearchService.grant(actor,"FOCUSGREATER");check(matrix.assemble(actor,new ItemStack(ArcaneContent.SALIS.get()))&&matrix.start(actor),"Actual greater-focus infusion failed to start");
  for(int n=0;n<1600&&matrix.job()!=null&&matrix.job().consumed()<2;n++)matrix.serverTick();check(matrix.job()!=null&&matrix.job().remaining().isEmpty()&&matrix.job().consumed()==2&&PrimordialPearl.wear(((InfusionPedestal)l.getBlockEntity(M.offset(0,-2,3))).item())==6,"Infusion did not pay essence and wear pearl once");
  for(var offering:matrix.job().offerings().subList(2,4))((InfusionPedestal)l.getBlockEntity(offering.position(M))).setItem(ItemStack.EMPTY);
 }
 static void collapse(ServerLevel l){
  for(var q:BlockPos.betweenClosed(P.east(24).offset(-4,-1,-4),P.east(24).offset(4,-1,4)))put(l,q,Blocks.STONE_BRICKS.defaultBlockState());
  var at=Vec3.atCenterOf(P.east(24).above(5));ItemStack pearl=ItemStack.EMPTY;
  for(int seed=0;seed<256&&pearl.isEmpty();seed++){
   l.getEntitiesOfClass(ItemEntity.class,new AABB(at,at).inflate(5)).forEach(Entity::discard);var r=new FluxRiftEntity(RiftContent.RIFT.get(),l);r.getRandom().setSeed(seed);r.setPos(at);r.setStability(100);r.setSize(100);r.beginCollapse();r.setSize(1);l.addFreshEntity(r);r.tick();check(r.isRemoved(),"Collapse failed to finish");var drops=l.getEntitiesOfClass(ItemEntity.class,new AABB(at,at).inflate(5));int total=drops.stream().filter(it->it.getItem().is(SimpleContent.ITEMS.get("void_seed").get())).mapToInt(it->it.getItem().getCount()).sum();check(total==10,"Collapse lost original size seed count");int count=drops.stream().mapToInt(it->it.getItem().getCount()).sum();r.tick();check(l.getEntitiesOfClass(ItemEntity.class,new AABB(at,at).inflate(5)).stream().mapToInt(it->it.getItem().getCount()).sum()==count,"Removed rift duplicated drops");for(var it:drops)if(it.getItem().getItem() instanceof PrimordialPearl){pearl=it.getItem().copy();check(PrimordialPearl.wear(pearl)>=4&&PrimordialPearl.wear(pearl)<=7,"Fresh pearl dropped instead of worn");}
  }check(!pearl.isEmpty(),"No pearl in deterministic collapse sample");
  var c=EntityTypes.COW.create(l,EntitySpawnReason.TRIGGERED);c.setNoAi(true);c.setNoGravity(true);c.setPos(at.add(1,0,0));l.addFreshEntity(c);var r=new FluxRiftEntity(RiftContent.RIFT.get(),l);r.setPos(at);r.setStability(-30);r.setSize(10);r.beginCollapse();r.setSize(1);l.addFreshEntity(r);r.tick();check(c.hasEffect(thaumcraft.taint.TaintContent.DISEASE.getHolder().orElseThrow())&&c.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS),"Collapse fall-through effects missing");c.discard();
  l.getEntitiesOfClass(ItemEntity.class,new AABB(at,at).inflate(5)).forEach(Entity::discard);var saved=new FluxRiftEntity(RiftContent.RIFT.get(),l);saved.setPos(at);saved.setStability(100);saved.setSize(100);saved.beginCollapse();saved.setSize(50);l.addFreshEntity(saved);
  put(l,CHEST,Blocks.CHEST.defaultBlockState());var chest=(ChestBlockEntity)l.getBlockEntity(CHEST);for(int i=0;i<8;i++)chest.setItem(i,PrimordialPearl.worn(i));chest.setItem(8,new ItemStack(SimpleContent.ITEMS.get("primordial_nugget").get(),9));chest.setItem(9,pearl);
  Thaumcraft.LOGGER.info("PRIMORDIAL_COLLAPSE_OK: deterministic real pearl loot wear 4..7, exact ten seeds from size 100, no duplicate drops and unstable disease/weakness effects");
 }
 @SubscribeEvent public static void joined(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(mode().equals("primordial-read")&&e.getEntity() instanceof FluxRiftEntity r&&r.blockPosition().distSqr(P.east(24).above(5))<4){check(r.collapsing()&&r.size()==50&&r.collapseSize()==100,"Reload reset original collapse size");r.beginCollapse();check(r.collapseSize()==100,"Second collapse reset loot size");seenReload=true;}}
 static void read(ServerLevel l){var chest=(ChestBlockEntity)l.getBlockEntity(CHEST);for(int i=0;i<8;i++)check(chest.getItem(i).getItem() instanceof PrimordialPearl&&PrimordialPearl.wear(chest.getItem(i))==i,"Pearl wear lost on restart");check(chest.getItem(8).getCount()==9,"Legacy fragments lost");matrix=(InfusionMatrix)l.getBlockEntity(M);check(matrix.job()!=null&&matrix.job().consumed()==2&&PrimordialPearl.wear(((InfusionPedestal)l.getBlockEntity(M.offset(0,-2,3))).item())==6,"Infusion restart repeated pearl consumption");for(var o:matrix.job().offerings().subList(2,4))((InfusionPedestal)l.getBlockEntity(o.position(M))).setItem(o.item().copy());for(int n=0;n<100&&matrix.job()!=null;n++)matrix.serverTick();check(matrix.job()==null&&((InfusionPedestal)l.getBlockEntity(M.below(2))).item().is(SimpleContent.ITEMS.get("focus_3").get())&&PrimordialPearl.wear(((InfusionPedestal)l.getBlockEntity(M.offset(0,-2,3))).item())==6,"Resumed infusion lost remainder or failed output");check(seenReload,"Native collapsing entity did not reload");int seeds=l.getEntitiesOfClass(ItemEntity.class,new AABB(P.east(24).above(5)).inflate(8)).stream().filter(it->it.getItem().is(SimpleContent.ITEMS.get("void_seed").get())).mapToInt(it->it.getItem().getCount()).sum();check(seeds==10,"Mid-collapse restart changed drop size");check(l.getBlockEntity(CondenserProbe.P) instanceof thaumcraft.condenser.Condenser&&thaumcraft.taint.TaintWorld.seed(l,TaintProbe.P)!=null,"Previous world content lost");Thaumcraft.LOGGER.info("PRIMORDIAL_RESTART_OK: eight wear states and legacy fragments retained, actual infusion resumed without second pearl payment, original collapse size survived, previous taint/condenser preserved");stage=5;l.getServer().halt(false);}
 static void gallery(ServerLevel l){int compatible=0;for(var holder:l.recipeAccess().getRecipes())if(holder.value() instanceof InfusionRecipe recipe){for(var component:recipe.components())if(component.test(item("primordial_nugget"))){compatible++;for(int wear=0;wear<8;wear++)check(component.test(PrimordialPearl.worn(wear)),"Migrated infusion rejected worn pearl");}if(recipe.research().equals("PRIMALCRUSHER")){var output=recipe.assemble(new InfusionInput(PrimordialPearl.worn(7),List.of(item("void_pick"),item("void_shovel"),item("elemental_pick"),item("elemental_shovel"))));check(output.getDamageValue()==0,"Pearl wear became output tool damage");}}check(compatible==6,"Missing legacy-compatible infusion recipes: "+compatible);for(var q:BlockPos.betweenClosed(P.offset(-5,-1,-1),P.offset(5,-1,1)))put(l,q,Blocks.GLOWSTONE.defaultBlockState());for(int i=0;i<3;i++)pedestal(l,P.offset(-4+i*4,0,0),PrimordialPearl.worn(new int[]{0,4,7}[i]));galleryRift=new FluxRiftEntity(RiftContent.RIFT.get(),l);galleryRift.setPos(Vec3.atCenterOf(P.north(3).above(3)));galleryRift.setSize(80);galleryRift.setSeed(23456);galleryRift.setStability(100);l.addFreshEntity(galleryRift);actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.teleportTo(l,P.getX()+.5,P.getY()+3,P.getZ()+10.5,Set.of(),180,12,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();check(net.minecraftforge.event.AnvilUpdateEvent.BUS.post(new net.minecraftforge.event.AnvilUpdateEvent(PrimordialPearl.worn(3),ItemStack.EMPTY,"renamed",0,actor))&&net.minecraftforge.event.AnvilUpdateEvent.BUS.post(new net.minecraftforge.event.AnvilUpdateEvent(new ItemStack(Items.STICK),PrimordialPearl.worn(7),"",0,actor)),"Original anvil cancellation missing");check(ResearchService.knows(actor,"PRIMPEARL")||ScanningService.observe(actor,PrimordialPearl.worn(7))&&ResearchService.knows(actor,"PRIMPEARL"),"Worn pearl discovery missing");var before=thaumcraft.persistence.PlayerWarpStore.read(actor).getOrThrow();var pulse=new FluxRiftEntity(RiftContent.RIFT.get(),l);pulse.setPos(actor.position().add(1,0,0));pulse.setStability(0);pulse.setSize(2);pulse.beginCollapse();pulse.setSize(1);pulse.tick();var after=thaumcraft.persistence.PlayerWarpStore.read(actor).getOrThrow();check(after.permanent()==before.permanent()&&after.normal()==Math.min(500,before.normal()+24)&&after.temporary()==Math.min(500,before.temporary()+24),"Real player collapse warp did not match original formula");check(thaumcraft.persistence.PlayerWarpStore.write(actor,before).result().isPresent(),"Fixture warp restoration failed");l.getEntitiesOfClass(ItemEntity.class,actor.getBoundingBox().inflate(3)).forEach(Entity::discard);actor.getInventory().clearContent();actor.getInventory().setItem(0,PrimordialPearl.worn(0));actor.getInventory().setItem(1,PrimordialPearl.worn(4));actor.getInventory().setItem(2,PrimordialPearl.worn(7));actor.getInventory().setSelectedSlot(0);l.getServer().getCommands().performPrefixedCommand(l.getServer().createCommandSourceStack(),"time set day");ready=true;stage=5;Thaumcraft.LOGGER.info("PRIMORDIAL_CLIENT_OK: pearl/nodule/mote models on real pedestals, eight-use items synchronized and native stable rift");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode().startsWith("primordial-"))return;var l=e.server().overworld();if(++ticks<80)return;if(stage==5){if(ready&&!collapsing&&actor.getInventory().getSelectedSlot()==8){collapsing=true;galleryRift.beginCollapse();due=l.getGameTime()+100;Thaumcraft.LOGGER.info("PRIMORDIAL_CLIENT_COLLAPSING: real size-80 collapse started");}if(ready&&collapsing&&due>0&&l.getGameTime()>=due){check(galleryRift.isRemoved(),"Native client collapse stalled");check(l.getEntitiesOfClass(ItemEntity.class,galleryRift.getBoundingBox().inflate(8)).stream().filter(it->it.getItem().is(SimpleContent.ITEMS.get("void_seed").get())).mapToInt(it->it.getItem().getCount()).sum()==8,"Native size-80 loot incorrect");due=0;Thaumcraft.LOGGER.info("PRIMORDIAL_CLIENT_COLLAPSE_OK: native timed collapse and exact eight void seeds");}return;}
  if(stage==0){if(!e.server().isDedicatedServer()){if(e.server().getPlayerList().getPlayers().isEmpty())return;actor=e.server().getPlayerList().getPlayers().getFirst();}else actor=fake(l);for(int x=189;x<=192;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);due=l.getGameTime()+50;stage=1;return;}
  if(stage==1&&l.getGameTime()>=due){if(mode().equals("primordial-read")){read(l);return;}l.getEntitiesOfClass(Entity.class,new AABB(P).inflate(40),en->!(en instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);for(var q:BlockPos.betweenClosed(P.offset(-10,-1,-9),P.offset(14,8,9)))put(l,q,q.getY()==P.getY()-1?Blocks.STONE_BRICKS.defaultBlockState():Blocks.AIR.defaultBlockState());if(mode().equals("primordial-client")){gallery(l);return;}basics(l);altar(l);collapse(l);Thaumcraft.LOGGER.info("PRIMORDIAL_WRITE_OK: native worn reagent paid mid-infusion; all pearl states and mid-collapse entity saved");stage=5;e.server().halt(false);}
 }
